import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"增益器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/gain/index.md","filePath":"v0.2.0-alpha/modules/gain/index.md"}'),r={name:"v0.2.0-alpha/modules/gain/index.md"};function i(n,t,l,h,c,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="增益器" tabindex="-1">增益器 <a class="header-anchor" href="#增益器" aria-label="Permalink to &quot;增益器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>gain</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>对每个输入值乘以一个固定系数，输出与输入保持相同的 item 速率和向量形状。正系数改变大小，负系数还使实数波形反相。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源.out → 增益器.in</code>。把信号源输出和增益器输出分别送到观察工具，即可比较幅度与相位；向量点表源也可接入匹配形状的增益器。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>增益是乘法系数，不是 dB 数。若希望幅度变为原来的两倍，使用系数 2；负系数使波形围绕零翻转，零系数输出零。</p><p>整数元素要求整数增益，并保留相应原生整数类型。向量输入的每个分量使用同一个系数，不会分别设置每分量增益。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>增益<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr><tr><td>元素类型<br><code>element_type</code></td><td><code>numeric_f64</code></td><td>实数 float32 (<code>numeric_f64</code>)；有符号 int16 (<code>int16</code>)；有符号 int32 (<code>int32</code>)</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线修改后，从真实回执和后续曲线确认效果。改变元素类型或向量长度需要重新准备，不能用增益设置隐式完成类型转换。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><h3 id="int16-向量-item、双端口延时与流标签" tabindex="-1">int16 向量 item、双端口延时与流标签 <a class="header-anchor" href="#int16-向量-item、双端口延时与流标签" aria-label="Permalink to &quot;int16 向量 item、双端口延时与流标签&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/vector-items-tags.cnsproj" download>下载 vector-items-tags.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>int16 向量 item、双端口延时与流标签</p><ul><li>每个 item 有 4 个 int16 分量；1 item 延时移动整组分量。标签 offset=1 表示第 2 个 item，显式选择第 3 分量观察。</li></ul><p>实数处理示例把信号源 1 接到增益器，输出应为原波形的两倍。向量示例则对整组 int16 分量乘以 2；在变量选择中明确选定同一下标，再比较处理前后。两组均为本机仿真。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>调大增益后波形看起来一样高？</strong> 图表自动纵轴可能同步放大范围，比较读数或使用相同的手动刻度。</p><p><strong>整数输入为什么不接受小数系数？</strong> 该路径采用整数增益；需要小数运算时，从相容的实数源和数据类型开始搭图。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/01-link-overview/">01 状态回传的链路全貌</a></li></ul>',35)])])}const u=e(r,[["render",i]]);export{m as __pageData,u as default};
